'use strict';
// Knowledge Base Admin page. Same look, layout and components as the Site Mailbox (src/mail + src/mailbox views).
// All KB text is placed with textContent in the browser (client.js); the server sends no KB content in this HTML.
const fs = require('fs');
const path = require('path');
const { esc } = require('../mail/sanitizer');
const { ICON, shell } = require('../mail/views');
const { CSS2, ICONS } = require('../mailbox/views');
// Site name and domain come from brand.json (identical for rfsafe.app: "RF Safe", rfsafe.app).
const SITE_B = (() => { try { return require('../brand'); } catch { return {}; } })();
const CLIENT = fs.readFileSync(path.join(__dirname, 'client.js'), 'utf8').split('rfsafe.app').join(SITE_B.site || 'rfsafe.app').split('RF Safe').join(SITE_B.name || 'RF Safe');
const CSS3 = `.lab{display:inline-block;font-size:11px;font-weight:650;padding:2px 8px;border-radius:999px;margin:3px 4px 0 0;border:1px solid var(--line);color:var(--muted)}
.lab.Proposed{color:var(--accent);border-color:rgba(110,231,255,.45)}.lab.In-debate{color:var(--accent2);border-color:rgba(167,139,250,.5)}.lab.Accuracy-check{color:#fbbf24;border-color:rgba(251,191,36,.5)}
.lab.Ready-to-publish{color:var(--ok);border-color:rgba(52,211,153,.5)}.lab.Updated{color:#07101f;background:var(--ok);border-color:transparent}.lab.Rejected{color:var(--hot);border-color:rgba(244,114,182,.5)}
.lab.Locked{color:#f59e0b;border-color:rgba(245,158,11,.5)}.lab.Needs-John{color:#07101f;background:linear-gradient(135deg,#fbbf24,var(--hot));border-color:transparent}
.thread{padding:14px 24px 30px;overflow:auto;flex:1}.msg{border:1px solid var(--line);border-radius:16px;background:var(--panel2);margin:12px 0;overflow:hidden}
.msg .mh{display:flex;gap:12px;align-items:center;padding:12px 14px;border-bottom:1px solid var(--line)}.msg .mh .av{width:36px;height:36px;border-radius:12px;font-size:13px}
.msg .mh b{display:block}.msg .mh small{color:var(--muted)}.msg .mb{padding:12px 16px;white-space:pre-wrap;overflow-wrap:anywhere}.msg.pass{border-color:rgba(52,211,153,.45)}.msg.fail{border-color:rgba(244,114,182,.5)}.msg.dec{border-color:rgba(167,139,250,.55)}
.verdict{font:700 12px ui-monospace,Menlo,monospace;padding:3px 9px;border-radius:8px;margin-left:auto}.verdict.ok{color:var(--ok);background:rgba(52,211,153,.12)}.verdict.no{color:var(--hot);background:rgba(244,114,182,.12)}
.diff{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.6 ui-sans-serif,system-ui,sans-serif;padding:12px 16px}.diff del{background:rgba(244,114,182,.18);color:var(--hot);text-decoration:line-through}.diff ins{background:rgba(52,211,153,.18);color:var(--ok);text-decoration:none}
.editor{border:1px solid var(--accent);border-radius:16px;padding:14px;margin:14px 0;background:var(--panel)}.editor textarea{width:100%;min-height:220px;padding:10px 12px;border-radius:12px;border:1px solid var(--line);background:var(--bg2);font:14px/1.5 ui-sans-serif,system-ui,sans-serif;color:var(--text)}
.bubble{display:inline-flex;align-items:center;gap:4px;font-size:11.5px;font-weight:700;padding:2px 8px;border-radius:999px;background:linear-gradient(135deg,var(--accent),var(--accent2));color:#07101f;margin-left:6px;cursor:pointer;border:0}
.lock{font-size:11.5px;color:#f59e0b;margin-left:6px}.feed .mv{padding:9px 0}.feed .mv b{color:var(--text)}.banner{margin:0 22px;padding:10px 14px;border-radius:12px;border:1px solid rgba(244,114,182,.5);background:rgba(244,114,182,.1);color:var(--hot)}
.ver{border-left:3px solid var(--line);padding:8px 12px;margin:10px 0}.ver.cur{border-left-color:var(--ok)}.ver pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.5 ui-sans-serif,system-ui,sans-serif;margin:8px 0;max-height:220px;overflow:auto;background:var(--bg2);padding:8px;border-radius:10px}
select{padding:9px 12px;border-radius:10px;border:1px solid var(--line);background:var(--bg2);color:var(--text)}
.lab.Competing{color:var(--accent2);border-color:rgba(167,139,250,.55);background:rgba(167,139,250,.1)}.lab.Not-chosen{color:var(--muted)}.lab.Undone{color:var(--hot);border-color:rgba(244,114,182,.5)}.lab.KB-gap{color:#fbbf24;border-color:rgba(251,191,36,.5);background:rgba(251,191,36,.08)}.lab.Claimed{color:var(--accent)}
.item.unread .subj{font-weight:800}.item.unread .from:before{content:"";display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--accent);margin-right:6px;box-shadow:0 0 8px var(--accent)}.item .snip{color:var(--muted);font-size:12.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
@keyframes kbfresh{0%{background:rgba(110,231,255,.2);box-shadow:inset 3px 0 0 var(--accent)}100%{background:transparent;box-shadow:inset 0 0 0 transparent}}.fresh{animation:kbfresh 2.6s ease-out}@media (prefers-reduced-motion:reduce){.fresh{animation:none;box-shadow:inset 3px 0 0 var(--accent)}}
.chips{display:flex;gap:6px;flex-wrap:wrap;padding:0 14px 8px}.chip{font-size:12px;padding:4px 10px;border-radius:999px;border:1px solid var(--line);background:transparent;color:var(--muted);cursor:pointer}.chip.on{color:#07101f;background:linear-gradient(135deg,var(--accent),var(--accent2));border-color:transparent}
.foot .btn{margin-left:8px;padding:4px 10px}.strip{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-top:10px}.sugg{display:inline-flex;align-items:center;gap:4px;border:1px solid var(--line);border-radius:12px;padding:5px 10px;background:var(--panel2);color:var(--text);cursor:pointer;font-size:12.5px}.sugg b{display:inline-grid;place-items:center;width:20px;height:20px;border-radius:7px;background:linear-gradient(135deg,var(--accent),var(--accent2));color:#07101f;font-size:11px}.sugg.on{border-color:var(--accent);box-shadow:0 0 0 2px rgba(110,231,255,.2)}.sugg .lab{margin:0}
.approved{border:1px solid rgba(52,211,153,.55);border-radius:16px;background:linear-gradient(135deg,rgba(52,211,153,.12),rgba(110,231,255,.06));margin:6px 0 14px;overflow:hidden}.approved .aph{padding:12px 16px;border-bottom:1px solid rgba(52,211,153,.3)}.approved .aph b{display:block;color:var(--ok);font-size:15px}.approved .aph small{color:var(--muted)}.aptabs{display:flex;gap:6px;padding:10px 14px 0}.apbody{padding:10px 16px}.apbody .plain{white-space:pre-wrap;overflow-wrap:anywhere;font:15px/1.6 ui-sans-serif,system-ui,sans-serif}.btn:disabled{opacity:.45;cursor:not-allowed}.apbody .reason{margin:6px 0}.approved .acts{padding:0 14px 12px}
.note{padding:10px 14px;border:1px dashed var(--line);border-radius:12px;color:var(--muted);margin:8px 0}.note a{color:var(--accent)}
.origin{display:inline-block;font-size:10.5px;font-weight:800;letter-spacing:.04em;text-transform:uppercase;padding:2px 7px;border-radius:6px;margin-left:4px;vertical-align:1px}.origin.local{color:#07101f;background:#fbbf24}.origin.api{color:#07101f;background:var(--accent)}
.switch.runner{border-color:rgba(167,139,250,.5)}.toast{position:fixed;bottom:22px;left:50%;transform:translateX(-50%);padding:10px 16px;border-radius:12px;background:var(--panel);border:1px solid var(--accent);z-index:50;box-shadow:0 10px 30px rgba(0,0,0,.3)}
.n.hot{color:#07101f;background:var(--accent)}`;
const NAV = [['inbox', 'Inbox', ICONS.inbox], ['needs', 'Needs John', ICONS.spam], ['locked', 'Locked / For John', ICONS.drafts], ['updated', 'Updated', ICONS.sent], ['rejected', 'Rejected', ICONS.trash]];
function appPage({ base, csrf, nonce, siteName }) {
  const nav = NAV.map(([f, label, ic]) => `<button class="nb" data-f="${f}" type="button">${ic}<span>${label}</span><span class="n" id="n-${f}"></span></button>`).join('');
  const body = `<header class="top glass"><div class="logo">${ICON}</div><div class="brand"><b>${esc(siteName)} Knowledge Base Admin</b><small>Proposals, reviews, versions and bot keys</small></div><div class="sp"></div><span class="pill" id="pill-live"><span class="dot"></span>Connecting…</span><span class="pill" id="pill-agents"><span class="dot"></span>Agents</span><span class="pill" id="pill-auto">Auto-publish</span>
<a class="btn" href="${base}" title="Mail">Mail</a><button class="btn" id="refresh" type="button" title="Refresh"><svg viewBox="0 0 24 24"><path d="M20 11a8 8 0 1 0-2.3 5.7M20 4v7h-7"/></svg><span>Refresh</span></button>
<form method="post" action="${base}/logout"><input type="hidden" name="csrf" value="${esc(csrf)}"><button class="btn" type="submit">Sign out</button></form></header>
<div id="banner"></div>
<main class="app" id="app"><nav class="nav glass" id="nav"><h4>Folders</h4>${nav}<button class="nb" data-v="activity" type="button">${ICONS.log}<span>Activity</span></button><h4>Knowledge base</h4><button class="nb" data-v="entries" type="button">${ICONS.archive}<span>Entries</span></button><h4>Bot settings</h4><button class="nb" data-v="agents" type="button">${ICONS.auto}<span>Agents</span></button><button class="nb" data-v="keys" type="button">${ICONS.keys}<span>Bot keys</span></button><button class="nb" data-v="prompts" type="button">${ICONS.drafts}<span>Role prompts</span></button><button class="nb" data-v="web" type="button">${ICONS.drafts}<span>Web research</span></button><button class="nb" data-v="controls" type="button">${ICONS.auto}<span>Controls</span><span class="n" id="n-auto">OFF</span></button></nav>
<section class="list glass" id="list"><div class="tools"><label class="search"><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/></svg><input id="q" type="search" placeholder="Search this folder" autocomplete="off"></label></div><div class="chips" id="chips"></div><div class="items" id="items"><div class="skel"></div><div class="skel"></div></div><div class="foot" id="foot">Loading…</div></section>
<section class="reader glass" id="reader"><div class="hero"><div><div class="orb"></div><h2>Select a thread</h2><p>Each thread holds the suggestions for one entry: the change, the improvement review, the accuracy review, then the decision. Approved changes show the final text, the reasoning and the before and after at the top. This page updates by itself.</p></div></div></section></main>`;
  return shell(siteName + ' Knowledge Base Admin', `<style>${CSS2}${CSS3}</style>` + body, nonce, CLIENT.replace('__BASE__', () => JSON.stringify(base)).replace('__CSRF__', () => JSON.stringify(csrf)));
}
module.exports = { appPage };
